package com.xdownload.mobile;
import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Parallel ranges only on a fresh file with a strong ETag. Never preallocate the resumable partial. */
final class ParallelEngine{
 static long transfer(String url,boolean http,File target,HttpEngine.Observer observer,int threads)throws IOException{
  HttpEngine.Info info=HttpEngine.probe(url,http);if(!info.ranges||info.size<4*1024*1024L||info.etag.isEmpty()||info.etag.startsWith("W/")||target.length()!=0||HttpEngine.html(info.mime)||HttpEngine.manifest(info.name,info.mime))return HttpEngine.download(url,http,target,"","",observer,0);
  int n=Math.max(2,Math.min(4,threads));File[] parts=new File[n];ExecutorService pool=Executors.newFixedThreadPool(n);AtomicBoolean abort=new AtomicBoolean();AtomicLong progress=new AtomicLong();List<Future<?>> tasks=new ArrayList<>();boolean success=false;
  try{observer.progress(0,info.size,info.etag,info.modified);for(int i=0;i<n;i++){final long start=info.size*i/n,end=info.size*(i+1)/n-1;final File p=new File(target.getPath()+".range"+i);parts[i]=p;tasks.add(pool.submit(()->{if(!observer.proceed()||abort.get())throw new IOException("Paused");HttpURLConnection c=HttpEngine.connectRange(url,http,"GET",start,end,info.etag);try{String range="bytes "+start+"-"+end+"/"+info.size;if(c.getResponseCode()!=206||!range.equals(c.getHeaderField("Content-Range"))||!info.etag.equals(c.getHeaderField("ETag")))throw new IOException("Server did not honor validated range");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(p)){byte[] buf=new byte[65536];long got=0;int count;while(!abort.get()&&observer.proceed()&&(count=in.read(buf))!=-1){got+=count;if(got>end-start+1)throw new IOException("Range overflow");out.write(buf,0,count);progress.addAndGet(count);}if(got!=end-start+1)throw new IOException("Range incomplete");}}finally{c.disconnect();}return null;}));}
   while(true){boolean done=true;for(Future<?> task:tasks)if(!task.isDone())done=false;observer.progress(progress.get(),info.size,info.etag,info.modified);if(!observer.proceed()){abort.set(true);return -1;}if(done)break;try{Thread.sleep(250);}catch(InterruptedException x){Thread.currentThread().interrupt();abort.set(true);return -1;}}
   for(Future<?> task:tasks)task.get();try(FileOutputStream out=new FileOutputStream(target)){byte[] buf=new byte[65536];for(File p:parts){try(InputStream in=new FileInputStream(p)){int count;while((count=in.read(buf))!=-1){if(!observer.proceed())return -1;out.write(buf,0,count);}}}out.getFD().sync();}if(target.length()!=info.size)throw new IOException("Combined file length mismatch");success=true;return info.size;
  }catch(ExecutionException x){throw new IOException("Parallel range validation failed",x);}catch(InterruptedException x){Thread.currentThread().interrupt();return -1;}finally{abort.set(true);pool.shutdownNow();try{pool.awaitTermination(16,TimeUnit.SECONDS);}catch(InterruptedException x){Thread.currentThread().interrupt();}for(File p:parts)if(p!=null)p.delete();if(!success)target.delete();}
 }
}